insert into public.diagnostic_questions(id,question_text,category,subcategory,difficulty,option_a,option_b,option_c,option_d,correct_answer,explanation,estimated_time_seconds,active) select id,question_text,category,subcategory,difficulty,option_a,option_b,option_c,option_d,correct_answer,explanation,estimated_time_seconds,true from jsonb_to_recordset($diagnostic$[{"id":"db-1-16","category":"database_technical","subcategory":"Constraints","question_text":"Which constraint limits values using a Boolean condition?","options":["CHECK","DEFAULT","INDEX","VIEW"],"correct_answer":"A","explanation":"CHECK validates a predicate for inserted or updated rows.","estimated_time_seconds":60,"difficulty":9.1,"option_a":"CHECK","option_b":"DEFAULT","option_c":"INDEX","option_d":"VIEW"},{"id":"db-1-17","category":"database_technical","subcategory":"Views","question_text":"A standard database view primarily stores what?","options":["A query definition","A copy of every result row","An index only","Transaction logs"],"correct_answer":"A","explanation":"A normal view stores its defining query, unlike a materialized view.","estimated_time_seconds":60,"difficulty":9.2,"option_a":"A query definition","option_b":"A copy of every result row","option_c":"An index only","option_d":"Transaction logs"},{"id":"db-1-18","category":"database_technical","subcategory":"Normalization","question_text":"A transitive dependency of a non-key attribute violates which normal form?","options":["Third normal form","First normal form","Second normal form only","Domain-key normal form only"],"correct_answer":"A","explanation":"3NF removes transitive dependencies on candidate keys.","estimated_time_seconds":60,"difficulty":9.3,"option_a":"Third normal form","option_b":"First normal form","option_c":"Second normal form only","option_d":"Domain-key normal form only"},{"id":"db-1-19","category":"database_technical","subcategory":"Joins","question_text":"What does an INNER JOIN return?","options":["Rows satisfying the join condition in both inputs","Every left row","Every possible pair only","Only unmatched rows"],"correct_answer":"A","explanation":"INNER JOIN retains matching combinations.","estimated_time_seconds":60,"difficulty":9.4,"option_a":"Rows satisfying the join condition in both inputs","option_b":"Every left row","option_c":"Every possible pair only","option_d":"Only unmatched rows"},{"id":"db-1-20","category":"database_technical","subcategory":"Ordering","question_text":"Without ORDER BY, which claim about result order is correct?","options":["No order is guaranteed","Primary-key order is guaranteed","Insertion order is guaranteed","Alphabetic order is guaranteed"],"correct_answer":"A","explanation":"Relational results are unordered unless ORDER BY is specified.","estimated_time_seconds":60,"difficulty":9.5,"option_a":"No order is guaranteed","option_b":"Primary-key order is guaranteed","option_c":"Insertion order is guaranteed","option_d":"Alphabetic order is guaranteed"},{"id":"db-2-1","category":"database_technical","subcategory":"SQL Filtering","question_text":"In a recruitment database scenario: Which clause filters rows before grouping?","options":["WHERE","HAVING","ORDER BY","DISTINCT"],"correct_answer":"A","explanation":"WHERE filters input rows; HAVING filters groups.","estimated_time_seconds":60,"difficulty":9,"option_a":"WHERE","option_b":"HAVING","option_c":"ORDER BY","option_d":"DISTINCT"},{"id":"db-2-2","category":"database_technical","subcategory":"Aggregation","question_text":"In a recruitment database scenario: Which clause filters aggregate groups?","options":["HAVING","WHERE","SELECT DISTINCT","LIMIT"],"correct_answer":"A","explanation":"HAVING is evaluated on groups after GROUP BY.","estimated_time_seconds":60,"difficulty":9.1,"option_a":"HAVING","option_b":"WHERE","option_c":"SELECT DISTINCT","option_d":"LIMIT"},{"id":"db-2-3","category":"database_technical","subcategory":"Keys","question_text":"In a recruitment database scenario: What property must every primary-key value have?","options":["It is unique and non-null","It may repeat","It must be text","It must reference another table"],"correct_answer":"A","explanation":"A primary key uniquely identifies a row and cannot be null.","estimated_time_seconds":60,"difficulty":9.2,"option_a":"It is unique and non-null","option_b":"It may repeat","option_c":"It must be text","option_d":"It must reference another table"},{"id":"db-2-4","category":"database_technical","subcategory":"Foreign Keys","question_text":"In a recruitment database scenario: What does a foreign key primarily enforce?","options":["Referential integrity","Sort order","Column encryption","Query caching"],"correct_answer":"A","explanation":"It constrains values to referenced candidate-key values.","estimated_time_seconds":60,"difficulty":9.3,"option_a":"Referential integrity","option_b":"Sort order","option_c":"Column encryption","option_d":"Query caching"},{"id":"db-2-5","category":"database_technical","subcategory":"Normalization","question_text":"In a recruitment database scenario: Which normal form removes partial dependency on a composite key?","options":["Second normal form","First normal form","Third normal form","BCNF only"],"correct_answer":"A","explanation":"2NF removes partial dependencies on a candidate key.","estimated_time_seconds":60,"difficulty":9.4,"option_a":"Second normal form","option_b":"First normal form","option_c":"Third normal form","option_d":"BCNF only"},{"id":"db-2-6","category":"database_technical","subcategory":"Transactions","question_text":"In a recruitment database scenario: Which ACID property ensures committed data survives failure?","options":["Durability","Atomicity","Isolation","Consistency"],"correct_answer":"A","explanation":"Durability preserves committed changes.","estimated_time_seconds":60,"difficulty":9.5,"option_a":"Durability","option_b":"Atomicity","option_c":"Isolation","option_d":"Consistency"},{"id":"db-2-7","category":"database_technical","subcategory":"Transactions","question_text":"In a recruitment database scenario: Which ACID property makes a transaction all-or-nothing?","options":["Atomicity","Isolation","Durability","Availability"],"correct_answer":"A","explanation":"Atomicity prevents partial transactions.","estimated_time_seconds":60,"difficulty":9,"option_a":"Atomicity","option_b":"Isolation","option_c":"Durability","option_d":"Availability"},{"id":"db-2-8","category":"database_technical","subcategory":"Indexes","question_text":"In a recruitment database scenario: What is the usual trade-off of adding an index?","options":["Faster reads but extra storage and write cost","Faster writes with no cost","Automatic normalization","Guaranteed uniqueness for every index"],"correct_answer":"A","explanation":"Indexes accelerate matching reads but must be maintained on writes.","estimated_time_seconds":60,"difficulty":9.1,"option_a":"Faster reads but extra storage and write cost","option_b":"Faster writes with no cost","option_c":"Automatic normalization","option_d":"Guaranteed uniqueness for every index"},{"id":"db-2-9","category":"database_technical","subcategory":"JOIN","question_text":"In a recruitment database scenario: Which join retains every row from the left table?","options":["LEFT JOIN","INNER JOIN","CROSS JOIN","SELF JOIN"],"correct_answer":"A","explanation":"LEFT JOIN preserves all left rows.","estimated_time_seconds":60,"difficulty":9.2,"option_a":"LEFT JOIN","option_b":"INNER JOIN","option_c":"CROSS JOIN","option_d":"SELF JOIN"},{"id":"db-2-10","category":"database_technical","subcategory":"NULL","question_text":"In a recruitment database scenario: Which predicate correctly tests missing SQL values?","options":["IS NULL","= NULL","== NULL","NULL()"],"correct_answer":"A","explanation":"NULL uses IS NULL because equality with NULL is unknown.","estimated_time_seconds":60,"difficulty":9.3,"option_a":"IS NULL","option_b":"= NULL","option_c":"== NULL","option_d":"NULL()"},{"id":"db-2-11","category":"database_technical","subcategory":"Grouping","question_text":"In a recruitment database scenario: A query selects department and COUNT(*). What else is normally required?","options":["GROUP BY department","ORDER BY department","HAVING department","DISTINCT COUNT"],"correct_answer":"A","explanation":"Non-aggregated selected columns normally belong in GROUP BY.","estimated_time_seconds":60,"difficulty":9.4,"option_a":"GROUP BY department","option_b":"ORDER BY department","option_c":"HAVING department","option_d":"DISTINCT COUNT"},{"id":"db-2-12","category":"database_technical","subcategory":"Isolation","question_text":"In a recruitment database scenario: What anomaly is prevented when a transaction cannot read uncommitted changes?","options":["Dirty read","Lost index","Dead column","Schema drift"],"correct_answer":"A","explanation":"Dirty reads observe another transaction's uncommitted work.","estimated_time_seconds":60,"difficulty":9.5,"option_a":"Dirty read","option_b":"Lost index","option_c":"Dead column","option_d":"Schema drift"},{"id":"db-2-13","category":"database_technical","subcategory":"Query Logic","question_text":"In a recruitment database scenario: COUNT(column_name) differs from COUNT(*) because it does what?","options":["Ignores NULL values in that column","Counts distinct values only","Counts tables","Returns text"],"correct_answer":"A","explanation":"COUNT(column) ignores NULL; COUNT(*) counts rows.","estimated_time_seconds":60,"difficulty":9,"option_a":"Ignores NULL values in that column","option_b":"Counts distinct values only","option_c":"Counts tables","option_d":"Returns text"},{"id":"db-2-14","category":"database_technical","subcategory":"Set Operations","question_text":"In a recruitment database scenario: What does UNION do by default?","options":["Removes duplicate rows","Keeps all duplicates","Joins columns by keys","Updates both queries"],"correct_answer":"A","explanation":"UNION applies duplicate elimination; UNION ALL does not.","es